// The sender is what ties a reply back to a row: an address belongs to one
// person, so the match is exact. Each test row has its own inbox for that
// reason; two rows sharing an address would make the match ambiguous.
//
// Pull the plain address out of whatever shape the Gmail node emits.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const raw = (j.from && j.from.value && j.from.value[0] && j.from.value[0].address)
    || (j.from && j.from.text)
    || j.From || j.from || '';
  const m = String(raw).match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
  if (!m) continue;
  out.push({ json: { sender: m[0].toLowerCase(), snippet: j.snippet || '' } });
}
return out;

// No row at crm_stage emailed for this sender: not one of ours, end quietly.
// A reply from someone we never wrote to is a normal thing to receive.
const out = [];
for (const item of $input.all()) {
  const body = item.json;
  const rows = Array.isArray(body) ? body : (Array.isArray(body.body) ? body.body : []);
  if (rows.length) out.push({ json: rows[0] });
}
return out;
